        manifestVersion: 2,
        id: fullId,
        name: name,
        version: '1.0.0',
        description: `A Synapse plugin for ${name}`,
        author: '',

        security: {
            allowedDomains: [],
            permissions: ['network']
        },

        connections: [],
        config: [],

        actions: [{
            id: triggerName,
            triggers: [triggerName],
            inputSchema: {
                type: 'object',
                properties: {
                    text: { type: 'string' }
                }
            }
        }]
    };

    fs.writeFileSync(
        path.join(dir, 'manifest.json'),
        JSON.stringify(manifest, null, 2) + '\n'
    );

    // =========================================================================
    // plugin.js — annotated with type references
    // =========================================================================

    const plugin = `// @ts-check
/// <reference path="./synapse-global.d.ts" />

// ${name} — Synapse Plugin
//
// Triggers: ${triggerName}
//
// SDK Quick Reference:
//   synapse.register()              — Handle an intent
//   synapse.fetch()                 — HTTP requests (proxied through host)
//   synapse.ui.show()               — Display custom HTML UI
//   synapse.ui.toast()              — Show a brief message
//   synapse.connections.connect()   — Connect a declared account
//   synapse.storage.get/set()       — Persistent key-value storage
//   synapse.mcp.callTool()          — Call a tool on a registered MCP server
//   synapse.success() / .fail()     — Return results
//
// Full docs: type "synapse." and let autocomplete guide you!

synapse.register('${triggerName}', async (ctx) => {
  synapse.log('${name}: ${triggerName} triggered');

  // ── Extract input ───────────────────────────────────────────────────────
  // ctx.input  — The shared content (text, image, URL, etc.)
  // ctx.llm    — AI analysis: detected intent + extracted entities
  // ctx.user   — User context: locale, timezone

  const text = ctx.llm.entities.text || ctx.input.text;

  if (!text) {
    return synapse.fail({
      reason: 'validation',
      message: 'Text input is required'
    });
  }

  // ── Make API requests ───────────────────────────────────────────────────
  // Uncomment and modify for your use case:
  //
  // const res = await synapse.fetch('https://api.example.com/endpoint', {
  //   method: 'POST',
  //   headers: { 'Content-Type': 'application/json' },
  //   body: JSON.stringify({ text }),
  //   connection: 'my_connection'  // Alias declared in manifest.json
  // });
  //
  // if (!res.ok) {
  //   const err = await res.json().catch(() => ({}));
  //   return synapse.fail({
  //     reason: 'api_error',
  //     message: err.message || 'Request failed'
  //   });
  // }
  //
  // const data = await res.json();

  // ── Return result ───────────────────────────────────────────────────────
  return synapse.success({
    message: 'Action completed!',
    input: text
  });
});
`;

    fs.writeFileSync(path.join(dir, 'plugin.js'), plugin);

    // =========================================================================
    // jsconfig.json — enables IntelliSense for plain JS
    // =========================================================================

    const jsconfig = {
        compilerOptions: {
            checkJs: true,
            target: 'ES2020',
            moduleResolution: 'node',
            types: []
        },
        include: [
            '*.js',
            'synapse-global.d.ts'
        ],
        exclude: [
            'node_modules'
        ]
    };

    fs.writeFileSync(
        path.join(dir, 'jsconfig.json'),
        JSON.stringify(jsconfig, null, 2) + '\n'
    );

    // =========================================================================
    // synapse-global.d.ts — copy type definitions into the plugin project
    // =========================================================================

    copyTypeDefs(dir);

    // =========================================================================
    // .vscode/settings.json — editor configuration
    // =========================================================================

    const vscodeSettings = {
        // Enable TypeScript checking for JavaScript files
        'js/ts.implicitProjectConfig.checkJs': true,
        // Associate manifest.json with the schema
        'json.schemas': [
            {
                fileMatch: ['manifest.json'],
                url: './node_modules/@synapse/sdk/schemas/manifest.schema.json'
            }
        ],
        // Recommend useful extensions
        'editor.quickSuggestions': {
            other: true,
            comments: false,
            strings: true
        }
    };

    fs.writeFileSync(
        path.join(dir, '.vscode', 'settings.json'),
        JSON.stringify(vscodeSettings, null, 2) + '\n'
    );

    // =========================================================================
    // README.md — comprehensive plugin documentation
    // =========================================================================

    const readme = `# ${name}

A Synapse plugin.

## Development Setup

This plugin comes with full editor support out of the box:

- **Autocomplete** — Type \`synapse.\` in \`plugin.js\` and see all available methods
- **Hover docs** — Hover over any method for documentation and examples
- **Type checking** — Errors are caught in your editor before runtime
- **Manifest validation** — \`manifest.json\` has autocomplete for all fields

### Prerequisites

Open this folder in VS Code (or any editor with TypeScript support).
IntelliSense works automatically — no \`npm install\` required.

## Plugin Structure

\`\`\`
${name}/
├── manifest.json          ← Plugin metadata and action contracts
├── plugin.js              ← Plugin code (your logic goes here)
├── jsconfig.json          ← Editor config for IntelliSense
├── synapse-global.d.ts    ← SDK type definitions (do not edit)
├── README.md              ← This file
└── .vscode/
    └── settings.json      ← VS Code settings
\`\`\`

## Triggers

- \`${triggerName}\` — Main action trigger

## Packaging

\`\`\`bash
synapse package .
\`\`\`

This creates a \`.synx\` file that can be installed in Synapse.

## SDK Quick Reference

\`\`\`javascript
// Intent handling
synapse.register('intent_name', async (ctx) => { ... });
synapse.success({ data });
synapse.fail({ reason: '...', message: '...' });
synapse.log('debug message');

// Network (all requests proxied through host)
const res = await synapse.fetch(url, { method, headers, body, connection: 'alias' });
await res.json();
await res.text();
res.ok / res.status / res.statusText

// UI
const result = await synapse.ui.show(html, { title, width, height });
await synapse.ui.toast('message');
const yes = await synapse.ui.confirm('question?');

// Connections (host-managed OAuth, API keys, and MCP OAuth)
await synapse.connections.connect('alias');
await synapse.connections.isConnected('alias');
await synapse.connections.disconnect('alias');

// Storage (persistent, per-plugin)
await synapse.storage.set('key', value);
const val = await synapse.storage.get('key');
await synapse.storage.delete('key');

// Config (encrypted settings from manifest.json)
const apiKey = await synapse.config.get('key');

// System (platform-specific)
const platform = await synapse.system.platform();
await synapse.system.runShortcut('name', input);          // iOS/macOS
await synapse.system.sendIntent({ action, extras });      // Android
await synapse.system.runAppleScript('tell app ...');      // macOS
await synapse.system.calendar.createEvent({ title, ... }); // iOS/macOS

// MCP (Model Context Protocol — host-managed tool servers)
// Declare MCP requirements on an action, then call allowlisted tools here.
// The host runs the MCP server; plugins never deal with transport.
const result = await synapse.mcp.callTool('server-name', 'tool-name', { arg: value });
if (result.success) {
  console.log(result.data);   // typed as TResponse
} else {
  console.error(result.error, result.code);  // e.g. 'BRIDGE_ERROR'
}

// File uploads
await synapse.upload({ fileRef, url });
\`\`\`

For full documentation, type \`synapse.\` in your editor and explore with autocomplete!
`;

    fs.writeFileSync(path.join(dir, 'README.md'), readme);

    return dir;
}

/**
 * Copy the SDK type definitions into the plugin directory.
 * Looks for synapse-global.d.ts in several possible locations
 * relative to where the CLI is installed.
 */
function copyTypeDefs(pluginDir: string): void {
    const possiblePaths = [
        // When CLI is run from the SDK repo (development)
        path.resolve(__dirname, '../../../types/synapse-global.d.ts'),
        // When CLI is run from the SDK repo (dist)
        path.resolve(__dirname, '../../types/synapse-global.d.ts'),
        // When installed as a package alongside @synapse/sdk
        path.resolve(__dirname, '../../../sdk/types/synapse-global.d.ts'),
        // Fallback: look up from CWD
        path.resolve(process.cwd(), 'types/synapse-global.d.ts'),
    ];

    for (const srcPath of possiblePaths) {
        if (fs.existsSync(srcPath)) {
            fs.copyFileSync(srcPath, path.join(pluginDir, 'synapse-global.d.ts'));
            return;
        }
    }

    // If we can't find the type definitions, write a stub with a helpful comment
    const stub = `// Synapse SDK Type Definitions
//
// This file should contain the full Synapse SDK type definitions.
// To get the latest version, copy synapse-global.d.ts from the
// Synapse SDK repository: types/synapse-global.d.ts
//
// Or run: synapse init --refresh-types

/** @type {any} */
declare const synapse: any;
declare const SynapseBridge: { postMessage(data: any): void };
`;

    fs.writeFileSync(path.join(pluginDir, 'synapse-global.d.ts'), stub);
}

text:
import { Bridge } from './bridge';
import {
    IntentHandler,
    SynapseContext,
    SynapseResult,
    SynapseRequestInit,
    SynapseResponseData,
    UiShowOptions,
    UploadParams,
    UploadResult,
    StorageValue,
    SynapsePlatform,
    AppleScriptOptions,
    CalendarEvent,
    CalendarInfo,
    CalendarQueryOptions,
    CalendarEventParams,
    McpCallOptions,
    McpCallResult
} from './types';

// =============================================================================
// SynapseResponse Class
// =============================================================================

/**
 * Response object returned from synapse.fetch().
 * Mirrors the native browser Response API for familiarity.
 * 
 * @example
 * const res = await synapse.fetch('https://api.example.com/data');
 * if (res.ok) {
 *   const data = await res.json();
 * }
 */
export class SynapseResponse {
    /** HTTP status code (e.g., 200, 404) */
    readonly status: number;
    /** True if status is in the 200-299 range */
    readonly ok: boolean;
    /** HTTP status text (e.g., "OK", "Not Found") */
    readonly statusText: string;
    /** Response headers */
    readonly headers: Record<string, string>;

    private _body: string;
    private _bodyUsed: boolean = false;

    constructor(data: SynapseResponseData) {
        this.status = data.status;
        this.ok = data.ok;
        this.statusText = data.statusText;
        this.headers = data.headers;
        this._body = data.body;
    }

    /**
     * Parse response body as JSON.
     * @throws Error if body has already been consumed or is not valid JSON.
     */
    async json<T = any>(): Promise<T> {
        if (this._bodyUsed) {
            throw new Error('Body has already been consumed');
        }
        this._bodyUsed = true;
        return JSON.parse(this._body);
    }

    /**
     * Get response body as plain text.
     * @throws Error if body has already been consumed.
     */
    async text(): Promise<string> {
        if (this._bodyUsed) {
            throw new Error('Body has already been consumed');
        }
        this._bodyUsed = true;
        return this._body;
    }
}

// =============================================================================
// Synapse Class
// =============================================================================

/**
 * Main Synapse SDK class.
 * Provides the API for plugins to interact with the host application.
 * 
 * @example
 * // Register an intent handler
 * synapse.register('create_event', async (ctx) => {
 *   const title = ctx.llm.entities.title;
 *   // Create event...
 *   return synapse.success({ eventId: '123' });
 * });
 */
export class Synapse {
    private handlers = new Map<string, IntentHandler>();

    // =========================================================================
    // Intent Registration
    // =========================================================================

    /**
     * Register a handler for a specific intent.
     * The handler will be called when the host dispatches this intent.
     * 
     * @param intent - The intent name (e.g., "create_event", "search")
     * @param handler - Async function to handle the intent
     * 
     * @example
     * synapse.register('create_jira_ticket', async (ctx) => {
     *   const { title, description } = ctx.llm.entities;
     *   const res = await synapse.fetch('https://jira.example.com/api/issues', {
     *     method: 'POST',
     *     body: JSON.stringify({ title, description })
     *   });
     *   if (res.ok) {
     *     return synapse.success({ ticketId: 'PROJ-123' });
     *   }
     *   return synapse.fail({ reason: 'api_error', message: 'Failed to create ticket' });
     * });
     */
    register(intent: string, handler: IntentHandler): void {
        this.handlers.set(intent, handler);
        Bridge.send('log', { message: `[Synapse] Registered intent: ${intent}` });
    }

    /**
     * Log a message to the host.
     * @param message - The message to log
     */
    log(message: string): void {
        Bridge.send('log', { message });
    }

    /**
     * Internal: Called by the host to dispatch an intent.
     * @internal
     */
    async _dispatch(intent: string, params: any): Promise<void> {
        const handler = this.handlers.get(intent);

        // Build the context object from params
        const ctx: SynapseContext = {
            input: params.input || { type: 'text' },
            llm: params.llm || { intent, entities: params },
            user: params.user
        };

        if (!handler) {
            return this.fail({
                reason: 'not_implemented',
                message: `No handler registered for intent: ${intent}`
            }) as any;
        }

        try {
            const result = await handler(ctx);
            Bridge.send('finished', result);
        } catch (e: any) {
            this.fail({
                reason: 'execution_error',
                message: e.message || 'Unknown error during execution'
            });
        }
    }

    // =========================================================================
    // Fetch API (Network)
    // =========================================================================

    /**
     * Make an HTTP request through the host.
     * Mirrors the native fetch() API for familiarity.
     * 
     * Note: Plugins cannot access the network directly. All requests
     * are proxied through the host, which may inject authentication
     * headers for configured OAuth providers.
     * 
     * @param url - The URL to fetch
     * @param init - Request options (method, headers, body)
     * @returns Promise resolving to a SynapseResponse
     * 
     * @example
     * // GET request
     * const res = await synapse.fetch('https://api.example.com/users');
     * const users = await res.json();
     * 
     * @example
     * // POST request with JSON body
     * const res = await synapse.fetch('https://api.example.com/users', {
     *   method: 'POST',
     *   headers: { 'Content-Type': 'application/json' },
     *   body: JSON.stringify({ name: 'John' }),
     *   provider: 'google'
     * });
     */
    async fetch(url: string, init?: SynapseRequestInit): Promise<SynapseResponse> {
        const request = {
            url,
            method: init?.method || 'GET',
            headers: init?.headers || {},
            body: typeof init?.body === 'object' ? JSON.stringify(init.body) : init?.body,
            provider: init?.provider,
            connection: init?.connection
        };

        const responseData = await Bridge.send('fetch', request, true);
        return new SynapseResponse(responseData);
    }

    // =========================================================================
    // UI Namespace
    // =========================================================================

    /**
     * UI utilities for displaying plugin interfaces.
     */
    ui = {
        /**
         * Display a custom HTML interface to the user.
         * Returns a promise that resolves when the UI is closed or sends data back.
         * 
         * The HTML can communicate back to the plugin using:
         * ```javascript
         * SynapseBridge.postMessage({ action: 'submit', data: {...} });
         * ```
         * 
         * @param html - HTML content to display
         * @param options - Display options (title, size, style)
         * @returns Promise resolving to data sent from the UI
         * 
         * @example
         * const result = await synapse.ui.show(`
         *   <button onclick="SynapseBridge.postMessage({selected: 'optionA'})">
         *     Option A
         *   </button>
         * `, { title: 'Select an option' });
         * console.log(result.selected); // 'optionA'
         */
        show: async (html: string, options?: UiShowOptions): Promise<any> => {
            return Bridge.send('ui_show', { html, options }, true);
        },

        /**
         * Show a brief toast/snackbar message.
         * 
         * @param message - Message to display
         * @param duration - Duration in ms (default: 3000)
         */
        toast: async (message: string, duration?: number): Promise<void> => {
            await Bridge.send('ui_toast', { message, duration: duration || 3000 });
        },

        /**
         * Show a confirmation dialog.
         * 
         * @param message - Question to ask
         * @param options - Button labels
         * @returns True if confirmed, false otherwise
         */
        confirm: async (message: string, options?: {
            confirmLabel?: string;
            cancelLabel?: string
        }): Promise<boolean> => {
            return Bridge.send('ui_confirm', { message, ...options }, true);
        }
    };

    // =========================================================================
    // Auth Namespace
    // =========================================================================

    /**
     * Authentication utilities.
     * OAuth flows are handled entirely by the host application.
     * Plugins just need to check auth status and trigger flows.
     */
    auth = {
        /**
         * Check if the plugin is authenticated with a provider.
         * 
         * @param provider - Provider ID (e.g., "jira", "google", "notion")
         * @returns True if authenticated
         * 
         * @example
         * if (!await synapse.auth.isAuthenticated('jira')) {
         *   await synapse.auth.authenticate('jira');
         * }
         */
        isAuthenticated: async (provider: string): Promise<boolean> => {
            return Bridge.send('auth_check', { provider }, true);
        },

        /**
         * Trigger the OAuth flow for a provider.
         * The host will open the native OAuth browser and handle the flow.
         * 
         * @param provider - Provider ID configured in the plugin manifest
         * @throws Error if authentication fails or is cancelled
         * 
         * @example
         * try {
         *   await synapse.auth.authenticate('notion');
         *   // User is now authenticated, subsequent fetch calls will include token
         * } catch (e) {
         *   console.log('User cancelled authentication');
         * }
         */
        authenticate: async (provider: string): Promise<void> => {
            return Bridge.send('auth_authenticate', { provider }, true);
        },

        /**
         * Clear authentication for a provider.
         * 
         * @param provider - Provider ID
         */
        logout: async (provider: string): Promise<void> => {
            await Bridge.send('auth_logout', { provider });
        },

        // Access tokens are never exposed to plugins. Use synapse.fetch
        // with `provider` to get Authorization injected by the host.
    };

    /**
     * Manifest v2 named user connections.
     *
     * Connections are resolved by the host from the plugin manifest. Tokens and
     * API keys are never returned to plugin JavaScript.
     */
    connections = {
        isConnected: async (alias: string): Promise<boolean> => {
            return Bridge.send('connection_check', { alias }, true);
        },

        connect: async (alias: string): Promise<void> => {
            return Bridge.send('connection_connect', { alias }, true);
        },

        disconnect: async (alias: string): Promise<void> => {
            await Bridge.send('connection_disconnect', { alias });
        }
    };

    // =========================================================================
    // Storage Namespace
    // =========================================================================

    /**
     * Persistent key-value storage for plugin settings and data.
     * Storage is scoped per-plugin and persisted securely by the host.
     */
    storage = {
        /**
         * Get a value from storage.
         * 
         * @param key - Storage key
         * @returns The stored value, or undefined if not found
         * 
         * @example
         * const defaultProject = await synapse.storage.get('defaultProject');
         */
        get: async <T extends StorageValue>(key: string): Promise<T | undefined> => {
            return Bridge.send('storage_get', { key }, true);
        },

        /**
         * Store a value.
         * 
         * @param key - Storage key
         * @param value - Value to store (string, number, boolean, or JSON-serializable object)
         * 
         * @example
         * await synapse.storage.set('defaultProject', 'PROJ-1');
         * await synapse.storage.set('settings', { theme: 'dark', notifications: true });
         */
        set: async (key: string, value: StorageValue): Promise<void> => {
            await Bridge.send('storage_set', { key, value });
        },

        /**
         * Delete a value from storage.
         * 
         * @param key - Storage key to delete
         */
        delete: async (key: string): Promise<void> => {
            await Bridge.send('storage_delete', { key });
        },

        /**
         * Clear all storage for this plugin.
         */
        clear: async (): Promise<void> => {
            await Bridge.send('storage_clear', {});
        }
    };

    // =========================================================================
    // Config Namespace
    // =========================================================================

    /**
     * Plugin configuration for API keys and user settings.
     * Values are stored encrypted and scoped to the plugin.
     * Config fields are declared in plugin.json and the host auto-generates UI.
     */
    config = {
        /**
         * Get a config value.
         * 
         * @param key - Config key as declared in plugin.json
         * @returns The config value or null if not set
         * 
         * @example
         * const apiKey = await synapse.config.get('openai_api_key');
         */
        get: async (key: string): Promise<string | null> => {
            return Bridge.send('config_get', { key }, true);
        },

        /**
         * Set a config value programmatically.
         * Note: Users typically set these via the plugin settings UI.
         * 
         * @param key - Config key
         * @param value - Value to store
         */
        set: async (key: string, value: string): Promise<void> => {
            await Bridge.send('config_set', { key, value });
        }
    };

    // =========================================================================
    // MCP Namespace
    // =========================================================================

    /**
     * Model Context Protocol (MCP) utilities.
     * Allows plugins to call tools on standard MCP servers managed by the host.
     */
    mcp = {
        /**
         * Call a tool on a registered MCP server.
         * 
         * This function returns a wrapped response object: `{ success: boolean, data?: TResponse, error?: string, code?: string }`.
         * Internally, it uses try-catch. If a catastrophic execution, bridge, or network error occurs, it catches the error
         * and returns it as a wrapped success: false result so plugins can handle failures gracefully without crashing.
         * 
         * @param serverName - Name of the MCP server as declared in plugin.json
         * @param toolName - Name of the tool to execute
         * @param args - Arguments to pass to the tool (JSON-serializable)
         * @param options - Execution options (timeout, routing policy)
         * @returns Promise resolving to a wrapped McpCallResult containing the typed data
         * 
         * @example
         * interface SpotifyArgs { deviceId?: string; }
         * interface SpotifyTrack { name: string; artist: string; }
         * 
         * const result = await synapse.mcp.callTool<SpotifyTrack, SpotifyArgs>(
         *   'spotify',
         *   'get-current-song',
         *   { deviceId: '123' },
         *   { timeoutMs: 5000 }
         * );
         * if (result.success) {
         *   console.log(`Now playing: ${result.data.name}`);
         * } else {
         *   console.error(`Error: ${result.error}`);
         * }
         */
        callTool: async <
            TResponse = any,
            TArgs extends Record<string, any> = Record<string, any>
        >(
            serverName: string,
            toolName: string,
            args?: TArgs,
            options?: McpCallOptions
        ): Promise<McpCallResult<TResponse>> => {
            try {
                const response = await Bridge.send(
                    'mcp_callTool',
                    {
                        serverName,
                        toolName,
                        arguments: args || {},
                        options: {
                            timeoutMs: options?.timeoutMs ?? 10000,
                            routingPolicy: options?.routingPolicy ?? 'prefer-local'
                        }
                    },
                    true
                );

                if (response && (response.success === false || response.isError === true)) {
                    return {
                        success: false,
                        error: response.error || response.message || 'Unknown MCP tool error',
                        code: response.code || 'UNKNOWN_ERROR'
                    };
                }

                // Standardize unwrapping: if the host returns an object with a success/data structure
                const data = response && typeof response === 'object' && 'data' in response ? response.data : response;

                return {
                    success: true,
                    data: data as TResponse
                };
            } catch (e: any) {
                // Catch bridge/catastrophic errors and wrap them into the result structure
                return {
                    success: false,
                    error: e.message || String(e),
                    code: 'BRIDGE_ERROR'
                };
            }
        }
    };

    // =========================================================================
    // System Namespace (Shortcuts, Intents, AppleScript & EventKit)
    // =========================================================================

    /**
     * System utilities for OS-level integration.
     * 
     * Provides access to:
     * - **Shortcuts** (iOS/macOS) — trigger Apple Shortcuts
     * - **Intents** (Android) — send Android Intents
     * - **AppleScript** (macOS) — execute AppleScript for any scriptable app
     * - **Calendar** (iOS/macOS) — read/write calendar events via EventKit
     * - **Platform** — detect the current OS
     */
    system = {
        /**
         * Get the current platform.
         * Use this to build cross-platform plugins with graceful fallbacks.
         * 
         * @returns The current platform identifier
         * 
         * @example
         * const platform = await synapse.system.platform();
         * if (platform === 'macos') {
         *   await synapse.system.runAppleScript('tell application "Notes" to activate');
         * } else {
         *   await synapse.system.runShortcut('Open Notes');
         * }
         */
        platform: async (): Promise<SynapsePlatform> => {
            return Bridge.send('system_platform', {}, true);
        },

        /**
         * Run an iOS Shortcut.
         * 
         * @param name - Name of the shortcut on the user's device
         * @param input - Optional text input for the shortcut
         * 
         * @example
         * await synapse.system.runShortcut('Save to Keep', 'Buy milk');
         */
        runShortcut: async (name: string, input?: string): Promise<void> => {
            return Bridge.send('system_runShortcut', { name, input }, true);
        },

        /**
         * Send an Android Intent.
         * 
         * @param options - Intent configuration
         * 
         * @example
         * await synapse.system.sendIntent({
         *   action: 'android.intent.action.SEND',
         *   type: 'text/plain',
         *   package: 'com.google.android.keep',
         *   extras: { 'android.intent.extra.TEXT': 'Buy milk' }
         * });
         */
        sendIntent: async (options: import('./types').IntentOptions): Promise<void> => {
            return Bridge.send('system_sendIntent', options, true);
        },

        // =====================================================================
        // AppleScript (macOS only)
        // =====================================================================

        /**
         * Execute an AppleScript on macOS.
         * Requires 'applescript' permission in the plugin manifest.
         * 
         * The host validates that the script only targets apps declared in
         * the manifest's `allowedApps` list, and blocks dangerous commands
         * like `do shell script`.
         * 
         * @param script - The AppleScript source code to execute
         * @param options - Execution options (timeout, etc.)
         * @returns The script's return value as a string, or null
         * 
         * @example
         * // Create an Apple Note
         * const result = await synapse.system.runAppleScript(`
         *   tell application "Notes"
         *     make new note at folder "Notes" with properties {name:"Hello", body:"World"}
         *   end tell
         * `);
         * 
         * @example
         * // Get current track from Apple Music
         * const track = await synapse.system.runAppleScript(`
         *   tell application "Music"
         *     if player state is playing then
         *       return name of current track
         *     end if
         *   end tell
         * `);
         */
        runAppleScript: async (script: string, options?: AppleScriptOptions): Promise<string | null> => {
            return Bridge.send('system_runAppleScript', {
                script,
                timeoutMs: options?.timeoutMs ?? 10000,
            }, true);
        },

        // =====================================================================
        // EventKit Calendar (iOS & macOS)
        // =====================================================================

        /**
         * Calendar API powered by EventKit.
         * Requires 'calendar' permission in the plugin manifest.
         * Works on both iOS and macOS.
         */
        calendar: {
            /**
             * List available calendars.
             * 
             * @returns Array of calendar info objects
             * 
             * @example
             * const calendars = await synapse.system.calendar.getCalendars();
             * const work = calendars.find(c => c.title === 'Work');
             */
            getCalendars: async (): Promise<CalendarInfo[]> => {
                return Bridge.send('system_calendar_getCalendars', {}, true);
            },

            /**
             * Query calendar events within a date range.
             * 
             * @param options - Query parameters (date range, optional calendar filter)
             * @returns Array of calendar events
             * 
             * @example
             * const events = await synapse.system.calendar.getEvents({
             *   startDate: '2026-04-06T00:00:00',
             *   endDate: '2026-04-07T00:00:00'
             * });
             */
            getEvents: async (options: CalendarQueryOptions): Promise<CalendarEvent[]> => {
                return Bridge.send('system_calendar_getEvents', options, true);
            },

            /**
             * Create a new calendar event.
             * 
             * @param event - Event parameters
             * @returns Object with the created event's ID
             * 
             * @example
             * const { eventId } = await synapse.system.calendar.createEvent({
             *   title: 'Team Standup',
             *   startDate: '2026-04-07T09:00:00',
             *   endDate: '2026-04-07T09:30:00',
             *   notes: 'Daily sync',
             *   location: 'Zoom'
             * });
             */
            createEvent: async (event: CalendarEventParams): Promise<{ eventId: string }> => {
                return Bridge.send('system_calendar_createEvent', event, true);
            },
        },
    };

    // =========================================================================
    // Upload
    // =========================================================================

    /**
     * Upload a file to a remote server.
     * Used for uploading images/attachments captured by the host.
     * 
     * @param params - Upload parameters
     * @returns Upload result with success status and server response
     * 
     * @example
     * const result = await synapse.upload({
     *   fileRef: ctx.input.imageRef,  // blob://capture_123
     *   url: 'https://api.example.com/attachments',
     *   fieldName: 'attachment',
     *   formFields: { ticketId: 'PROJ-123' },
     *   provider: 'google'
     * });
     */
    async upload(params: UploadParams): Promise<UploadResult> {
        return Bridge.send('upload', params, true);
    }

    // =========================================================================
    // Result Helpers
    // =========================================================================

    /**
     * Create a success result.
     * 
     * @param data - Data to include in the result
     * @returns SynapseResult with status 'success'
     * 
     * @example
     * return synapse.success({ 
     *   ticketId: 'PROJ-123',
     *   link: 'https://jira.example.com/browse/PROJ-123'
     * });
     */
    success(data: any = {}): SynapseResult {
        return {
            status: 'success',
            data,
            link: data.link
        };
    }

    /**
     * Create a failure result and notify the host.
     * 
     * @param error - Error details
     * @returns SynapseResult with status 'fail'
     * 
     * @example
     * return synapse.fail({ 
     *   reason: 'validation_error',
     *   message: 'Title is required',
     *   retryable: true
     * });
     */
    fail(error: { reason: string; message: string; retryable?: boolean }): SynapseResult {
        Bridge.send('finished', { status: 'error', ...error });
        return {
            status: 'fail',
            error: error.message
        };
    }

    // =========================================================================
    // Internal Bridge
    // =========================================================================

    /**
     * Internal bridge methods for host communication.
     * @internal
     */
    _bridge = {
        resolve: (id: string, response: any, error?: string) =>
            Bridge.handleResponse(id, response, error)
    };
}

// =============================================================================
// Singleton Export
// =============================================================================

/** Global Synapse SDK instance */
export const synapse = new Synapse();

// Expose on globalThis for direct access from evaluated plugin code
(globalThis as any).synapse = synapse;

content.text:
import { Bridge } from './bridge';
import {
    IntentHandler,
    SynapseContext,
    SynapseResult,
    SynapseRequestInit,
    SynapseResponseData,
    UiShowOptions,
    UploadParams,
    UploadResult,
    StorageValue,
    SynapsePlatform,
    AppleScriptOptions,
    CalendarEvent,
    CalendarInfo,
    CalendarQueryOptions,
    CalendarEventParams,
    McpCallOptions,
    McpCallResult
} from './types';

// =============================================================================
// SynapseResponse Class
// =============================================================================

/**
 * Response object returned from synapse.fetch().
 * Mirrors the native browser Response API for familiarity.
 * 
 * @example
 * const res = await synapse.fetch('https://api.example.com/data');
 * if (res.ok) {
 *   const data = await res.json();
 * }
 */
export class SynapseResponse {
    /** HTTP status code (e.g., 200, 404) */
    readonly status: number;
    /** True if status is in the 200-299 range */
    readonly ok: boolean;
    /** HTTP status text (e.g., "OK", "Not Found") */
    readonly statusText: string;
    /** Response headers */
    readonly headers: Record<string, string>;

    private _body: string;
    private _bodyUsed: boolean = false;

    constructor(data: SynapseResponseData) {
        this.status = data.status;
        this.ok = data.ok;
        this.statusText = data.statusText;
        this.headers = data.headers;
        this._body = data.body;
    }

    /**
     * Parse response body as JSON.
     * @throws Error if body has already been consumed or is not valid JSON.
     */
    async json<T = any>(): Promise<T> {
        if (this._bodyUsed) {
            throw new Error('Body has already been consumed');
        }
        this._bodyUsed = true;
        return JSON.parse(this._body);
    }

    /**
     * Get response body as plain text.
     * @throws Error if body has already been consumed.
     */
    async text(): Promise<string> {
        if (this._bodyUsed) {
            throw new Error('Body has already been consumed');
        }
        this._bodyUsed = true;
        return this._body;
    }
}

// =============================================================================
// Synapse Class
// =============================================================================

/**
 * Main Synapse SDK class.
 * Provides the API for plugins to interact with the host application.
 * 
 * @example
 * // Register an intent handler
 * synapse.register('create_event', async (ctx) => {
 *   const title = ctx.llm.entities.title;
 *   // Create event...
 *   return synapse.success({ eventId: '123' });
 * });
 */
export class Synapse {
    private handlers = new Map<string, IntentHandler>();

    // =========================================================================
    // Intent Registration
    // =========================================================================

    /**
     * Register a handler for a specific intent.
     * The handler will be called when the host dispatches this intent.
     * 
     * @param intent - The intent name (e.g., "create_event", "search")
     * @param handler - Async function to handle the intent
     * 
     * @example
     * synapse.register('create_jira_ticket', async (ctx) => {
     *   const { title, description } = ctx.llm.entities;
     *   const res = await synapse.fetch('https://jira.example.com/api/issues', {
     *     method: 'POST',
     *     body: JSON.stringify({ title, description })
     *   });
     *   if (res.ok) {
     *     return synapse.success({ ticketId: 'PROJ-123' });
     *   }
     *   return synapse.fail({ reason: 'api_error', message: 'Failed to create ticket' });
     * });
     */
    register(intent: string, handler: IntentHandler): void {
        this.handlers.set(intent, handler);
        Bridge.send('log', { message: `[Synapse] Registered intent: ${intent}` });
    }

    /**
     * Log a message to the host.
     * @param message - The message to log
     */
    log(message: string): void {
        Bridge.send('log', { message });
    }

    /**
     * Internal: Called by the host to dispatch an intent.
     * @internal
     */
    async _dispatch(intent: string, params: any): Promise<void> {
        const handler = this.handlers.get(intent);

        // Build the context object from params
        const ctx: SynapseContext = {
            input: params.input || { type: 'text' },
            llm: params.llm || { intent, entities: params },
            user: params.user
        };

        if (!handler) {
            return this.fail({
                reason: 'not_implemented',
                message: `No handler registered for intent: ${intent}`
            }) as any;
        }

        try {
            const result = await handler(ctx);
            Bridge.send('finished', result);
        } catch (e: any) {
            this.fail({
                reason: 'execution_error',
                message: e.message || 'Unknown error during execution'
            });
        }
    }

    // =========================================================================
    // Fetch API (Network)
    // =========================================================================

    /**
     * Make an HTTP request through the host.
     * Mirrors the native fetch() API for familiarity.
     * 
     * Note: Plugins cannot access the network directly. All requests
     * are proxied through the host, which may inject authentication
     * headers for configured OAuth providers.
     * 
     * @param url - The URL to fetch
     * @param init - Request options (method, headers, body)
     * @returns Promise resolving to a SynapseResponse
     * 
     * @example
     * // GET request
     * const res = await synapse.fetch('https://api.example.com/users');
     * const users = await res.json();
     * 
     * @example
     * // POST request with JSON body
     * const res = await synapse.fetch('https://api.example.com/users', {
     *   method: 'POST',
     *   headers: { 'Content-Type': 'application/json' },
     *   body: JSON.stringify({ name: 'John' }),
     *   provider: 'google'
     * });
     */
    async fetch(url: string, init?: SynapseRequestInit): Promise<SynapseResponse> {
        const request = {
            url,
            method: init?.method || 'GET',
            headers: init?.headers || {},
            body: typeof init?.body === 'object' ? JSON.stringify(init.body) : init?.body,
            provider: init?.provider,
            connection: init?.connection
        };

        const responseData = await Bridge.send('fetch', request, true);
        return new SynapseResponse(responseData);
    }

    // =========================================================================
    // UI Namespace
    // =========================================================================

    /**
     * UI utilities for displaying plugin interfaces.
     */
    ui = {
        /**
         * Display a custom HTML interface to the user.
         * Returns a promise that resolves when the UI is closed or sends data back.
         * 
         * The HTML can communicate back to the plugin using:
         * ```javascript
         * SynapseBridge.postMessage({ action: 'submit', data: {...} });
         * ```
         * 
         * @param html - HTML content to display
         * @param options - Display options (title, size, style)
         * @returns Promise resolving to data sent from the UI
         * 
         * @example
         * const result = await synapse.ui.show(`
         *   <button onclick="SynapseBridge.postMessage({selected: 'optionA'})">
         *     Option A
         *   </button>
         * `, { title: 'Select an option' });
         * console.log(result.selected); // 'optionA'
         */
        show: async (html: string, options?: UiShowOptions): Promise<any> => {
            return Bridge.send('ui_show', { html, options }, true);
        },

        /**
         * Show a brief toast/snackbar message.
         * 
         * @param message - Message to display
         * @param duration - Duration in ms (default: 3000)
         */
        toast: async (message: string, duration?: number): Promise<void> => {
            await Bridge.send('ui_toast', { message, duration: duration || 3000 });
        },

        /**
         * Show a confirmation dialog.
         * 
         * @param message - Question to ask
         * @param options - Button labels
         * @returns True if confirmed, false otherwise
         */
        confirm: async (message: string, options?: {
            confirmLabel?: string;
            cancelLabel?: string
        }): Promise<boolean> => {
            return Bridge.send('ui_confirm', { message, ...options }, true);
        }
    };

    // =========================================================================
    // Auth Namespace
    // =========================================================================

    /**
     * Authentication utilities.
     * OAuth flows are handled entirely by the host application.
     * Plugins just need to check auth status and trigger flows.
     */
    auth = {
        /**
         * Check if the plugin is authenticated with a provider.
         * 
         * @param provider - Provider ID (e.g., "jira", "google", "notion")
         * @returns True if authenticated
         * 
         * @example
         * if (!await synapse.auth.isAuthenticated('jira')) {
         *   await synapse.auth.authenticate('jira');
         * }
         */
        isAuthenticated: async (provider: string): Promise<boolean> => {
            return Bridge.send('auth_check', { provider }, true);
        },

        /**
         * Trigger the OAuth flow for a provider.
         * The host will open the native OAuth browser and handle the flow.
         * 
         * @param provider - Provider ID configured in the plugin manifest
         * @throws Error if authentication fails or is cancelled
         * 
         * @example
         * try {
         *   await synapse.auth.authenticate('notion');
         *   // User is now authenticated, subsequent fetch calls will include token
         * } catch (e) {
         *   console.log('User cancelled authentication');
         * }
         */
        authenticate: async (provider: string): Promise<void> => {
            return Bridge.send('auth_authenticate', { provider }, true);
        },

        /**
         * Clear authentication for a provider.
         * 
         * @param provider - Provider ID
         */
        logout: async (provider: string): Promise<void> => {
            await Bridge.send('auth_logout', { provider });
        },

        // Access tokens are never exposed to plugins. Use synapse.fetch
        // with `provider` to get Authorization injected by the host.
    };

    /**
     * Manifest v2 named user connections.
     *
     * Connections are resolved by the host from the plugin manifest. Tokens and
     * API keys are never returned to plugin JavaScript.
     */
    connections = {
        isConnected: async (alias: string): Promise<boolean> => {
            return Bridge.send('connection_check', { alias }, true);
        },

        connect: async (alias: string): Promise<void> => {
            return Bridge.send('connection_connect', { alias }, true);
        },

        disconnect: async (alias: string): Promise<void> => {
            await Bridge.send('connection_disconnect', { alias });
        }
    };

    // =========================================================================
    // Storage Namespace
    // =========================================================================

    /**
     * Persistent key-value storage for plugin settings and data.
     * Storage is scoped per-plugin and persisted securely by the host.
     */
    storage = {
        /**
         * Get a value from storage.
         * 
         * @param key - Storage key
         * @returns The stored value, or undefined if not found
         * 
         * @example
         * const defaultProject = await synapse.storage.get('defaultProject');
         */
        get: async <T extends StorageValue>(key: string): Promise<T | undefined> => {
            return Bridge.send('storage_get', { key }, true);
        },

        /**
         * Store a value.
         * 
         * @param key - Storage key
         * @param value - Value to store (string, number, boolean, or JSON-serializable object)
         * 
         * @example
         * await synapse.storage.set('defaultProject', 'PROJ-1');
         * await synapse.storage.set('settings', { theme: 'dark', notifications: true });
         */
        set: async (key: string, value: StorageValue): Promise<void> => {
            await Bridge.send('storage_set', { key, value });
        },

        /**
         * Delete a value from storage.
         * 
         * @param key - Storage key to delete
         */
        delete: async (key: string): Promise<void> => {
            await Bridge.send('storage_delete', { key });
        },

        /**
         * Clear all storage for this plugin.
         */
        clear: async (): Promise<void> => {
            await Bridge.send('storage_clear', {});
        }
    };

    // =========================================================================
    // Config Namespace
    // =========================================================================

    /**
     * Plugin configuration for API keys and user settings.
     * Values are stored encrypted and scoped to the plugin.
     * Config fields are declared in plugin.json and the host auto-generates UI.
     */
    config = {
        /**
         * Get a config value.
         * 
         * @param key - Config key as declared in plugin.json
         * @returns The config value or null if not set
         * 
         * @example
         * const apiKey = await synapse.config.get('openai_api_key');
         */
        get: async (key: string): Promise<string | null> => {
            return Bridge.send('config_get', { key }, true);
        },

        /**
         * Set a config value programmatically.
         * Note: Users typically set these via the plugin settings UI.
         * 
         * @param key - Config key
         * @param value - Value to store
         */
        set: async (key: string, value: string): Promise<void> => {
            await Bridge.send('config_set', { key, value });
        }
    };

    // =========================================================================
    // MCP Namespace
    // =========================================================================

    /**
     * Model Context Protocol (MCP) utilities.
     * Allows plugins to call tools on standard MCP servers managed by the host.
     */
    mcp = {
        /**
         * Call a tool on a registered MCP server.
         * 
         * This function returns a wrapped response object: `{ success: boolean, data?: TResponse, error?: string, code?: string }`.
         * Internally, it uses try-catch. If a catastrophic execution, bridge, or network error occurs, it catches the error
         * and returns it as a wrapped success: false result so plugins can handle failures gracefully without crashing.
         * 
         * @param serverName - Name of the MCP server as declared in plugin.json
         * @param toolName - Name of the tool to execute
         * @param args - Arguments to pass to the tool (JSON-serializable)
         * @param options - Execution options (timeout, routing policy)
         * @returns Promise resolving to a wrapped McpCallResult containing the typed data
         * 
         * @example
         * interface SpotifyArgs { deviceId?: string; }
         * interface SpotifyTrack { name: string; artist: string; }
         * 
         * const result = await synapse.mcp.callTool<SpotifyTrack, SpotifyArgs>(
         *   'spotify',
         *   'get-current-song',
         *   { deviceId: '123' },
         *   { timeoutMs: 5000 }
         * );
         * if (result.success) {
         *   console.log(`Now playing: ${result.data.name}`);
         * } else {
         *   console.error(`Error: ${result.error}`);
         * }
         */
        callTool: async <
            TResponse = any,
            TArgs extends Record<string, any> = Record<string, any>
        >(
            serverName: string,
            toolName: string,
            args?: TArgs,
            options?: McpCallOptions
        ): Promise<McpCallResult<TResponse>> => {
            try {
                const response = await Bridge.send(
                    'mcp_callTool',
                    {
                        serverName,
                        toolName,
                        arguments: args || {},
                        options: {
                            timeoutMs: options?.timeoutMs ?? 10000,
                            routingPolicy: options?.routingPolicy ?? 'prefer-local'
                        }
                    },
                    true
                );

                if (response && (response.success === false || response.isError === true)) {
                    return {
                        success: false,
                        error: response.error || response.message || 'Unknown MCP tool error',
                        code: response.code || 'UNKNOWN_ERROR'
                    };
                }

                // Standardize unwrapping: if the host returns an object with a success/data structure
                const data = response && typeof response === 'object' && 'data' in response ? response.data : response;

                return {
                    success: true,
                    data: data as TResponse
                };
            } catch (e: any) {
                // Catch bridge/catastrophic errors and wrap them into the result structure
                return {
                    success: false,
                    error: e.message || String(e),
                    code: 'BRIDGE_ERROR'
                };
            }
        }
    };

    // =========================================================================
    // System Namespace (Shortcuts, Intents, AppleScript & EventKit)
    // =========================================================================

    /**
     * System utilities for OS-level integration.
     * 
     * Provides access to:
     * - **Shortcuts** (iOS/macOS) — trigger Apple Shortcuts
     * - **Intents** (Android) — send Android Intents
     * - **AppleScript** (macOS) — execute AppleScript for any scriptable app
     * - **Calendar** (iOS/macOS) — read/write calendar events via EventKit
     * - **Platform** — detect the current OS
     */
    system = {
        /**
         * Get the current platform.
         * Use this to build cross-platform plugins with graceful fallbacks.
         * 
         * @returns The current platform identifier
         * 
         * @example
         * const platform = await synapse.system.platform();
         * if (platform === 'macos') {
         *   await synapse.system.runAppleScript('tell application "Notes" to activate');
         * } else {
         *   await synapse.system.runShortcut('Open Notes');
         * }
         */
        platform: async (): Promise<SynapsePlatform> => {
            return Bridge.send('system_platform', {}, true);
        },

        /**
         * Run an iOS Shortcut.
         * 
         * @param name - Name of the shortcut on the user's device
         * @param input - Optional text input for the shortcut
         * 
         * @example
         * await synapse.system.runShortcut('Save to Keep', 'Buy milk');
         */
        runShortcut: async (name: string, input?: string): Promise<void> => {
            return Bridge.send('system_runShortcut', { name, input }, true);
        },

        /**
         * Send an Android Intent.
         * 
         * @param options - Intent configuration
         * 
         * @example
         * await synapse.system.sendIntent({
         *   action: 'android.intent.action.SEND',
         *   type: 'text/plain',
         *   package: 'com.google.android.keep',
         *   extras: { 'android.intent.extra.TEXT': 'Buy milk' }
         * });
         */
        sendIntent: async (options: import('./types').IntentOptions): Promise<void> => {
            return Bridge.send('system_sendIntent', options, true);
        },

        // =====================================================================
        // AppleScript (macOS only)
        // =====================================================================

        /**
         * Execute an AppleScript on macOS.
         * Requires 'applescript' permission in the plugin manifest.
         * 
         * The host validates that the script only targets apps declared in
         * the manifest's `allowedApps` list, and blocks dangerous commands
         * like `do shell script`.
         * 
         * @param script - The AppleScript source code to execute
         * @param options - Execution options (timeout, etc.)
         * @returns The script's return value as a string, or null
         * 
         * @example
         * // Create an Apple Note
         * const result = await synapse.system.runAppleScript(`
         *   tell application "Notes"
         *     make new note at folder "Notes" with properties {name:"Hello", body:"World"}
         *   end tell
         * `);
         * 
         * @example
         * // Get current track from Apple Music
         * const track = await synapse.system.runAppleScript(`
         *   tell application "Music"
         *     if player state is playing then
         *       return name of current track
         *     end if
         *   end tell
         * `);
         */
        runAppleScript: async (script: string, options?: AppleScriptOptions): Promise<string | null> => {
            return Bridge.send('system_runAppleScript', {
                script,
                timeoutMs: options?.timeoutMs ?? 10000,
            }, true);
        },

        // =====================================================================
        // EventKit Calendar (iOS & macOS)
        // =====================================================================

        /**
         * Calendar API powered by EventKit.
         * Requires 'calendar' permission in the plugin manifest.
         * Works on both iOS and macOS.
         */
        calendar: {
            /**
             * List available calendars.
             * 
             * @returns Array of calendar info objects
             * 
             * @example
             * const calendars = await synapse.system.calendar.getCalendars();
             * const work = calendars.find(c => c.title === 'Work');
             */
            getCalendars: async (): Promise<CalendarInfo[]> => {
                return Bridge.send('system_calendar_getCalendars', {}, true);
            },

            /**
             * Query calendar events within a date range.
             * 
             * @param options - Query parameters (date range, optional calendar filter)
             * @returns Array of calendar events
             * 
             * @example
             * const events = await synapse.system.calendar.getEvents({
             *   startDate: '2026-04-06T00:00:00',
             *   endDate: '2026-04-07T00:00:00'
             * });
             */
            getEvents: async (options: CalendarQueryOptions): Promise<CalendarEvent[]> => {
                return Bridge.send('system_calendar_getEvents', options, true);
            },

            /**
             * Create a new calendar event.
             * 
             * @param event - Event parameters
             * @returns Object with the created event's ID
             * 
             * @example
             * const { eventId } = await synapse.system.calendar.createEvent({
             *   title: 'Team Standup',
             *   startDate: '2026-04-07T09:00:00',
             *   endDate: '2026-04-07T09:30:00',
             *   notes: 'Daily sync',
             *   location: 'Zoom'
             * });
             */
            createEvent: async (event: CalendarEventParams): Promise<{ eventId: string }> => {
                return Bridge.send('system_calendar_createEvent', event, true);
            },
        },
    };

    // =========================================================================
    // Upload
    // =========================================================================

    /**
     * Upload a file to a remote server.
     * Used for uploading images/attachments captured by the host.
     * 
     * @param params - Upload parameters
     * @returns Upload result with success status and server response
     * 
     * @example
     * const result = await synapse.upload({
     *   fileRef: ctx.input.imageRef,  // blob://capture_123
     *   url: 'https://api.example.com/attachments',
     *   fieldName: 'attachment',
     *   formFields: { ticketId: 'PROJ-123' },
     *   provider: 'google'
     * });
     */
    async upload(params: UploadParams): Promise<UploadResult> {
        return Bridge.send('upload', params, true);
    }

    // =========================================================================
    // Result Helpers
    // =========================================================================

    /**
     * Create a success result.
     * 
     * @param data - Data to include in the result
     * @returns SynapseResult with status 'success'
     * 
     * @example
     * return synapse.success({ 
     *   ticketId: 'PROJ-123',
     *   link: 'https://jira.example.com/browse/PROJ-123'
     * });
     */
    success(data: any = {}): SynapseResult {
        return {
            status: 'success',
            data,
            link: data.link
        };
    }

    /**
     * Create a failure result and notify the host.
     * 
     * @param error - Error details
     * @returns SynapseResult with status 'fail'
     * 
     * @example
     * return synapse.fail({ 
     *   reason: 'validation_error',
     *   message: 'Title is required',
     *   retryable: true
     * });
     */
    fail(error: { reason: string; message: string; retryable?: boolean }): SynapseResult {
        Bridge.send('finished', { status: 'error', ...error });
        return {
            status: 'fail',
            error: error.message
        };
    }

    // =========================================================================
    // Internal Bridge
    // =========================================================================

    /**
     * Internal bridge methods for host communication.
     * @internal
     */
    _bridge = {
        resolve: (id: string, response: any, error?: string) =>
            Bridge.handleResponse(id, response, error)
    };
}

// =============================================================================
// Singleton Export
// =============================================================================

/** Global Synapse SDK instance */
export const synapse = new Synapse();

// Expose on globalThis for direct access from evaluated plugin code
(globalThis as any).synapse = synapse;

