        if (msg.type === 'finished') {
            console.log('[Host] Action Finished:', msg.payload);
            if (msg.payload.status === 'success') {
                console.log('✅ TEST PASSED');
                process.exit(0);
            } else {
                console.log('❌ TEST FAILED');
