  void _resolvePromise(String id, dynamic data, {String? error}) {
    final dataJson = jsonEncode(data);
    final errorArg = error != null ? jsonEncode(error) : 'null';

    final code = "synapse._bridge.resolve('$id', $dataJson, $errorArg)";
